    if ($v_count === 0) {
        @mysqli_query($conn, 'INSERT IGNORE INTO `evaluation_versions` VALUES (1,47,1,\'Version 1\',\'Administration\',\'City of Manila\',\'Medium\',0.00,0.00,0.00,0.00,6.50,\'Conditional Support pending Local Grid Compatibility and Phased Tariff Protections\',\'{\\"ai_analysis\\":\\"For Manila City municipal operations, integrating with a modernized national clean energy grid will stabilize power supply for critical public services and reduce emergency operational costs. Enhanced energy resilience will protect local businesses from costly power disruptions, thereby fortifying the city\\\'s overall economic stability. Ultimately, community welfare will improve through reduced reliance on diesel backup generators and lower urban ambient air pollution.\\",\\"reason\\":\\"The policy strategically aligns with long-term urban resilience goals, but implementation risks regarding local municipal utility integration and transitional consumer cost increases must be actively mitigated.\\",\\"improvements\\":[\\"Establish clear municipal public-private partnership frameworks to co-finance local smart-grid distribution upgrades without overburdening city coffers.\\",\\"Include explicit low-income tariff shielding provisions to protect vulnerable households from potential short-term transition costs.\\",\\"Formulate joint task forces between national energy agencies and local government units to streamline urban rights-of-way permitting for grid infrastructure.\\"],\\"criteria\\":{\\"economic\\":{\\"level\\":\\"High\\",\\"reason\\":\\"While requiring substantial initial capital investment for infrastructure upgrades, grid modernization yields significant long-term economic returns through reduced transmission losses and energy price stabilization.\\"},\\"social\\":{\\"level\\":\\"Medium\\",\\"reason\\":\\"Upgrading national grid reliability ensures equitable electricity access and minimizes power outages, though construction phases may cause minor local community disruptions.\\"